    [10] = {code = "San d'Oria 3-1", s = {["|10"] = "When you enter Davoi, speak with Zantaviat the NPC near the tree.", ["|11"] = "You will need to find 3 targetable ! marks and check them.", ["|12"] = "Return to Zantaviat then return to the Gate Guard.", ["|2"] = "Accept the mission Infiltrate Davoi from the Gate Guard.", ["|3"] = "Speak to Prince Trion who can be reached by clicking on the Door: Prince Royal's Rm at (G/H-7) of Chateau d'Oraguille for a cutscene.", ["|4"] = "Zone into Davoi for a cutscene.", ["|5"] = "Speak with Quemaricond, patrolling around (H-7), when it is safe to drop Invisibility.", ["|6"] = "Return to Prince Trion to complete the Mission.", ["|8"] = "Talk to any Gate Guard and accept the Mission.", ["|9"] = "Make your way to Davoi."}},
