    [15] = {code = "San d'Oria 5-2", s = {["|1"] = "Speak to Halver for a some text about Prince Trion.", ["|10"] = "Head for Xarcabard.", ["|11"] = "Enter Castle Zvahl Baileys, follow the one-way path until you come to the first intersection.", ["|12"] = "Turn left and follow the right wall until you reach the next map.", ["|13"] = "On the next map, turn right and head all the way to the top right corner of the map.", ["|14"] = "Head up the stairs and you will be on the second \"level\".", ["|15"] = "Next, get to the top left part of the map and walk back down the set of stairs and you'll be back on the first \"level\".", ["|16"] = "Work your way into the center of the map from here and you will be in an outdoor courtyard.", ["|17"] = "At this point you can use the Shadow Lord Shirt, if you have it.", ["|18"] = "Inside, walk out of the hallway and turn right.", ["|19"] = "Once on the second level, you will be overlooking a room below.", ["|2"] = "Examine Door: Prince Royal's Rm for a cutscene with Trion.", ["|20"] = "Follow the teleporters four times until you reach a new map.", ["|21"] = "The Shadow Lord has 2 forms.", ["|22"] = "While immune to magic, he will use Dark Nova (AOE Darkness damage) and can cast Black Magic.", ["|23"] = "During physical immunity, he can use a variety of TP attacks, including Giga Slash, Kick Back and Umbra Smash.", ["|24"] = "Defeating the first form will get you a cutscene.", ["|25"] = "The second form will only use AoE attacks, but has less HP (approximately 4,000 HP).", ["|3"] = "Castle Zvahl Keep Home Point #1 is fastest way.", ["|4"] = "Click on the door to the Throne Room for a cutscene.", ["|5"] = "Click on the door again and select \"The Shadow Lord Battle\" to start the BCNM.", ["|6"] = "After you clear the BCNM, you'll get another cutscene.", ["|7"] = "Return to Halver for your reward: Rank 6 and 20,000 Gil.", ["|8"] = "Check the door to the Great Hall for a final cutscene involving the royal family.", ["|9"] = "While you're here, check Door: Prince Royal's Rm at the back of Chateau d'Oraguille for an additional cutscene and to learn Trust: Trion,"}},
