    [17] = {code = "San d'Oria 6-2", s = {["|1"] = "You'll be instructed to go see Prince Trion.", ["|10"] = "Return to the Heavy Stone Door in King Ranperre's Tomb again for another cutscene.", ["|11"] = "Return to a Gate Guard to complete the Mission.", ["|2"] = "If you're low level, gather a party or use Trusts.", ["|3"] = "Head for (H-8) in King Ranperre's Tomb on Map 1.", ["|4"] = "When ready, check the Heavy Stone Door to spawn three (3) Skeleton NMs: Corrupted Soffeil (BLM), Corrupted Yorgos (WAR) and Corrupted", ["|5"] = "When defeated, check the Heavy Stone Door again, and enter.", ["|6"] = "Talk to any Gate Guard.", ["|7"] = "You must talk to the Gate Guard once more to have them tell you that the deciphering will take some time.", ["|8"] = "Zone and talk to the Guard again who will tell you to see Prince Trion.", ["|9"] = "Return to Prince Trion and speak with him for a cutscene."}},
    [18] = {code = "San d'Oria 7-1", s = {["|1"] = "Head to the Cathedral in Northern San d'Oria and go to the Papal Chambers, located on the third floor at (M-6).", ["|2"] = "If you're low level, form a party and/or use Trusts.", ["|3"] = "Head to Bostaunieux Oubliette, which can be accessed from Chateau d'Oraguille (I-8).", ["|4"] = "When prepared, check the ??? to spawn an Orc NM Marauder Dvogzog.", ["|5"] = "Check the ??? again to receive the Ancient San d'Orian tablet.", ["|6"] = "Return to the Cathedral and visit the Papal Chambers for the final cutscene.", ["|7"] = "Unity Warp: If you have dropped down the Sewer Lid in Bostaunieux Oubliette at least once, the Level 122 Unity Warp can teleport you", ["|8"] = "Proto-Waypoint: The West Ronfaure Proto-Waypoint will get you directly to your destination, provided you've already unlocked it."}},
    [19] = {code = "San d'Oria 7-2", s = {["|1"] = "Speak with a Gate Guard who will instruct you to go to the Garden in Chateau d'Oraguille.", ["|2"] = "Head for Chateau d'Oraguille and go towards (F-8).", ["|3"] = "Return to the Gate Guard to receive the Mission.", ["|4"] = "If you're low level, gather a party and/or use Trusts.", ["|5"] = "You will have to reach Horlais Peak, accessible via travelling through Ghelsba Outpost and Yughott Grotto.", ["|6"] = "Once you're there, get ready and enter the BC.", ["|7"] = "When finished, you'll receive another cutscene, and receive the Crystal dowser.", ["|8"] = "Head back to San d'Oria and speak to any Gate Guard to finish the mission."}},
    [20] = {code = "San d'Oria 8-1", s = {["|1"] = "Go to Chateau d'Oraguille, where you'll receive a cutscene upon entering.", ["|2"] = "Speak to Halver for instructions.", ["|3"] = "Travel to the Quicksand Caves Map 2.", ["|4"] = "You will need to drop down a hole at (E-11) to reach an isolated portion of the map.", ["|5"] = "Once you drop down, travel to the Fountain of Kings at (G-14).", ["|6"] = "Clear the area and check Fountain of Kings.", ["|7"] = "Check the Fountain of Kings again, after the bodies disappear, for some Drops of Amnio.", ["|8"] = "Return to Halver.", ["|9"] = "Wait 1 Earth minute, then exit the Chateau (into Northern San d'Oria) for another cutscene."}},
    [21] = {code = "San d'Oria 8-2", s = {["|1"] = "Head to Chateau d'Oraguille and check the Great Hall door for a cutscene.", ["|10"] = "You will be awarded Rank 9 and 80,000 Gil.", ["|2"] = "Speak with Rahal (H-9, western door directly across from the entry way) to receive the Crystal dowser and further instructions.", ["|3"] = "Head to the Temple of Uggalepih and farm a Prelate Key from the Tonberry Stabbers on Map 3/4.", ["|4"] = "Make your way through the Temple until you reach the door at (I-10) on Map 2, that can only be opened by killing the Temple Guardian.", ["|5"] = "Pass into the big room, and head upstairs and through the door at (J-10) which requires the Prelate Key.", ["|6"] = "In the south hallway examine the three ??? in any order.", ["|7"] = "After you have all 3 keys, select the second door (H-10) to spawn 2 Doll NMs: Nio-Hum and Nio-A.", ["|8"] = "After the Dolls have been defeated, check the door again for a cutscene.", ["|9"] = "Return to Chateau d'Oraguille and check the Great Hall door for a cutscene."}},
